"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["7597"],{17306(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.inscricao.conflito_de_concorrencia","status":409,"titulo":"Esta inscri\xe7\xe3o foi alterada por outra opera\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.inscricao.conflito_de_concorrencia","requisitos":[],"oQueAconteceu":["Duas opera\xe7\xf5es sobre a mesma inscri\xe7\xe3o chegaram ao mesmo tempo, por abas ou\\ndispositivos diferentes, ou por uma repeti\xe7\xe3o do mesmo pedido. A que confirmou\\npor \xfaltimo encontrou a inscri\xe7\xe3o j\xe1 alterada pela outra e foi recusada, para\\nque nenhuma sobrescreva a outra sem querer. Nada do que esse pedido enviou foi\\ngravado.","O erro descreve uma corrida que j\xe1 passou, e n\xe3o um estado que permanece: a\\nresposta traz `retryable: true`, e repetir o pedido depois de reler a\\ninscri\xe7\xe3o pode dar certo."],"comoResolver":["Leia a inscri\xe7\xe3o de novo, confira como ela ficou depois da outra opera\xe7\xe3o e\\nrepita o envio ou o cancelamento com o `ETag` atual no `If-Match`. Repetir o\\npedido com o `ETag` antigo \xe9 recusado por outra causa, porque a inscri\xe7\xe3o j\xe1\\nmudou (`uniplus.selecao.inscricao.precondicao_falhou`). Se a outra opera\xe7\xe3o j\xe1\\nfez o que se pretendia, como enviar a mesma inscri\xe7\xe3o, n\xe3o h\xe1 mais nada a\\nfazer."],"ondeAparece":["Envio da inscri\xe7\xe3o do candidato","Cancelamento da inscri\xe7\xe3o do candidato"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);